//@category Getaway
import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.address.*; import java.io.*;
public class VerifyAsm extends GhidraScript { public void run() throws Exception { String out=getScriptArgs()[0]; try(PrintWriter pw=new PrintWriter(out)){ for(long[] r: new long[][]{{0x144aa0,0x144ab4},{0x3d7098,0x3d711c},{0x3d6fe8,0x3d702c}}){ Address a=toAddr(r[0]); clearListing(a,toAddr(r[1])); disassemble(a); while(a.getOffset()<r[1]){ Instruction in=getInstructionAt(a); pw.printf("%s %s\n",a,in); a=a.add(in!=null?in.getLength():4);} pw.println(); } } } }
